function unpack(): CityData[] {
  const out: CityData[] = [];
  for (const block of PACKED.split('\n')) {
    const split = block.indexOf('^');
    const country = block.slice(0, split);
    let lat = 0;
    let lon = 0;
    for (const row of block.slice(split + 1).split('|')) {
      const f = row.split('~');
      lat += parseInt(f[2], 36);
      lon += parseInt(f[3], 36);
      const city: CityData = {
        name: f[0],
        country,
        region: f[1] || undefined,
        lat: lat / 10000,
        lon: lon / 10000,
      };
      if (f[4]) city.population = parseInt(f[4], 36);
      out.push(city);
    }
  }
  return out;
}

export const CITIES_FALLBACK: CityData[] = unpack();
